arguments.command:
# Find ALL zip signatures in the file
perl -e '
open(F, "<", "/app/varsea/disks/sub1/subA/subAlpha/ae3f4c.dat") or die;
binmode F;
my $data;
read(F, $data, -s "/app/varsea/disks/sub1/subA/subAlpha/ae3f4c.dat");
close F;
print "File size: ", length($data), "\n";
# PK\x03\x04 = local file header
# PK\x01\x02 = central directory
# PK\x05\x06 = end of central directory
for my $sig ("PK\x03\x04", "PK\x01\x02", "PK\x05\x06") {
    my @offsets;
    my $pos = 0;
    while ((my $idx = index($data, $sig, $pos)) != -1) {
        push @offsets, $idx;
        $pos = $idx + 1;
    }
    (my $disp = $sig) =~ s/[^\x20-\x7e]/sprintf("\\x%02x", ord($&))/ge;
    print "Sig $disp at: ", join(", ", @offsets), "\n";
}
'

