# Alternative CRC check using a different approach
perl -e '
# Pure perl CRC32
my @crc_table;
for my $n (0..255) {
    my $c = $n;
    for (1..8) {
        $c = ($c & 1) ? (0xEDB88320 ^ ($c >> 1)) : ($c >> 1);
    }
    $crc_table[$n] = $c;
}
sub crc32 {
    my $crc = 0xFFFFFFFF;
    for my $b (map { ord($_) } split //, $_[0]) {
        $crc = $crc_table[($crc ^ $b) & 0xFF] ^ ($crc >> 8);
    }
    return $crc ^ 0xFFFFFFFF;
}

