for my $n (0..255) {
    my $c = $n;
    for (1..8) {
        $c = ($c & 1) ? (0xEDB88320 ^ ($c >> 1)) : ($c >> 1);
    }
    $crc_table[$n] = $c;
}
sub crc32 {
    my $crc = 0xFFFFFFFF;
    for my $b (map { ord($_) } split //, $_[0]) {
        $crc = $crc_table[($crc ^ $b) & 0xFF] ^ ($crc >> 8);
    }
    return $crc ^ 0xFFFFFFFF;
}

# Test candidate password: 8XDP5Q2RT9ZK7VB3BV4WW54
my $password = "8XDP5Q2RT9ZK7VB3BV4WW54";
my $content = "PASSWORD=$password\n";
printf("Password: %s (len=%d)\n", $password, length($password));
printf("Content: %s (len=%d)\n", $content, length($content));
my $crc = crc32($content);
printf("CRC-32: %08x\n", $crc);
printf("Expected: b0725dc4\n");
printf("Match: %s\n", $crc == 0xb0725dc4 ? "YES!" : "NO");

# Also try without newline
$content = "PASSWORD=$password";
$crc = crc32($content);
printf("\nWithout newline - CRC: %08x, Match: %s\n", $crc, $crc == 0xb0725dc4 ? "YES!" : "NO");

# Also try with \r\n
$content = "PASSWORD=$password\r\n";
$crc = crc32($content);
printf("With CRLF - CRC: %08x, Match: %s\n", $crc, $crc == 0xb0725dc4 ? "YES!" : "NO");
'

